public List<Pick> allocate(String sku, int qty, List<Bin> bins) {
    // Проверяем, что запрошенное количество положительное.
    // Если qty <= 0, выбрасываем исключение, так как аллокация нулевого или отрицательного количества не имеет смысла.
    if (qty <= 0) throw new IllegalArgumentException("qty must be positive");

    // Фильтруем список ячеек хранения (bins), оставляя только те, которые:
    // 1. Содержат нужный SKU (идентификатор товара).
    // 2. Имеют доступное количество (available > 0).
    // Затем сортируем отфильтрованные ячейки по дате истечения срока годности (expiresAt) по возрастанию.
    // Это реализует стратегию FEFO (First Expired, First Out) — сначала отгружаются товары с ближайшим сроком годности.
    // Результат собираем в новый список candidates.
    List<Bin> candidates = bins.stream()
        .filter(b -> b.getSku().equals(sku) && b.getAvailable() > 0)
        .sorted(Comparator.comparing(Bin::getExpiresAt))
        .collect(Collectors.toList());

    // Инициализируем список для хранения результатов аллокации (список "пиков" — заборов товара из ячеек).
    List<Pick> picks = new ArrayList<>();

    // Переменная left хранит остаток количества, который еще нужно забрать.
    // Изначально это все запрошенное количество qty.
    int left = qty;

    // Итерируемся по отсортированным кандидатам (ячейкам с подходящим товаром).
    for (Bin b : candidates) {
        // Если остаток (left) стал равен нулю, значит, мы уже забрали все нужное количество.
        // Прерываем цикл, так как дальнейшие ячейки не нужны.
        if (left == 0) break;

        // Определяем, сколько товара можно забрать из текущей ячейки b.
        // Берем минимум между оставшимся необходимым количеством (left) и доступным количеством в ячейке (b.getAvailable()).
        // Это гарантирует, что мы не заберем больше, чем есть в ячейке, и не заберем больше, чем нужно.
        int take = Math.min(left, b.getAvailable());

        // Создаем объект Pick, который фиксирует факт забора 'take' единиц товара из ячейки с id 'b.getId()'.
        // Добавляем этот объект в список результатов picks.
        picks.add(new Pick(b.getId(), take));

        // Уменьшаем оставшееся необходимое количество на то, что мы только что забрали.
        left -= take;
    }

    // После завершения цикла проверяем, остался ли неудовлетворенный остаток (left > 0).
    // Если да, значит, суммарного доступного количества по всем подходящим ячейкам не хватило для выполнения заказа.
    // Выбрасываем исключение InsufficientStockException, передавая ему SKU, фактически отгруженное количество (qty - left)

