public async Task<SyncResult> SyncAccountsAsync(DateTime since, CancellationToken ct)
{
    // Инициализируем объект для хранения результатов синхронизации
    var result = new SyncResult();

    // Получаем список аккаунтов из CRM, которые были изменены после указанной даты
    var accounts = await _crm.GetAccountsModifiedSinceAsync(since, ct);

    // Проходим по каждому полученному аккаунту
    foreach (var account in accounts)
    {
        // Пропускаем аккаунты, у которых отсутствует или пустой ИНН,
        // так как без ИНН невозможно корректно идентифицировать контрагента в ERP
        if (string.IsNullOrWhiteSpace(account.Inn))
        {
            // Добавляем ID пропущенного аккаунта в список пропущенных
            result.Skipped.Add(account.Id);
            // Переходим к следующему аккаунту
            continue;
        }

        // Пытаемся найти существующего контрагента в ERP по ИНН
        var existing = await _erp.FindCounterpartyByInnAsync(account.Inn, ct);

        // Если контрагент с таким ИНН не найден в ERP, создаем нового
        if (existing == null)
            await _erp.CreateCounterpartyAsync(Map(account), ct);
        // Если контрагент найден, но данные в CRM новее, чем в ERP, обновляем запись
        else if (existing.ModifiedAt < account.ModifiedAt)
            await _erp.UpdateCounterpartyAsync(existing.Id, Map(account), ct);

        // Увеличиваем счетчик успешно обработанных аккаунтов
        result.Processed++;
    }

    // Возвращаем итоговый результат синхронизации
    return result;
}
