```kotlin
fun planLoads(orders: List<Order>, capacityKg: Double): List<List<Order>> {
    // Проверяем, что вместимость грузового отсека положительна.
    // Если передано нулевое или отрицательное значение, выбрасываем исключение,
    // так как планирование загрузки в таком случае невозможно.
    require(capacityKg > 0) { "capacityKg must be positive" }

    // Находим заказы, вес которых превышает максимальную вместимость одного грузового отсека.
    // Такие заказы невозможно разместить ни в одном отсеке, поэтому считаем их ошибкой данных.
    val oversized = orders.filter { it.weightKg > capacityKg }

    // Если найдены заказы, превышающие вместимость, выбрасываем исключение
    // с указанием ID проблемных заказов для диагностики.
    if (oversized.isNotEmpty()) {
        throw IllegalArgumentException("orders exceed capacity: ${oversized.map { it.id }}")
    }

    // Список грузовых отсеков (каждый отсек — это список заказов, размещённых в нём).
    val loads = mutableListOf<MutableList<Order>>()

    // Список оставшейся свободной вместимости для каждого грузового отсека.
    // Индексы в этом списке соответствуют индексам в списке loads.
    val free = mutableListOf<Double>()

    // Сортируем заказы по убыванию веса.
    // Это эвристика "First Fit Decreasing" (FFD): сначала размещаем самые тяжёлые заказы,
    // что обычно приводит к более компактному и эффективному распределению по отсекам.
    for (order in orders.sortedByDescending { it.weightKg }) {

        // Ищем первый грузовой отсек, в котором достаточно свободного места
        // для размещения текущего заказа.
        val i = free.indexOfFirst { it >= order.weightKg }

        if (i >= 0) {
            // Если подходящий отсек найден, добавляем заказ в этот отсек
            // и уменьшаем оставшуюся свободную вместимость этого отсека.
            loads[i].add(order)
            free[i] -= order.weightKg
        } else {
            // Если ни в одном существующем отсеке не хватает места,
            // создаём новый грузовой отсек, добавляем в него текущий заказ
            // и записываем оставшуюся свободную вместимость нового отсека.
            loads.add(mutableListOf(order))
            free.add(capacityKg - order.weightKg)
        }
    }

    // Возвращаем список грузовых отсеков, каждый из которых содержит список заказов.
    return loads
}
```

