/// Вычисляет оценку релевантности документа для запроса с использованием алгоритма BM25.
///
/// # Аргументы
/// * `tf` - частота термина (term frequency) в текущем документе.
/// * `doc_len` - длина текущего документа (количество слов/токенов).
/// * `avg_len` - средняя длина документов в коллекции.
/// * `df` - количество документов, содержащих данный термин (document frequency).
/// * `n_docs` - общее количество документов в коллекции.
///
/// # Возвращаемое значение
/// * `f64` - оценка BM25 для данного термина в данном документе.
pub fn bm25(tf: u32, doc_len: u32, avg_len: f64, df: u32, n_docs: u32) -> f64 {
    // Параметры настройки алгоритма BM25:
    // K1 контролирует влияние частоты термина (tf) на оценку.
    // B контролирует влияние длины документа на нормализацию.
    const K1: f64 = 1.2;
    const B: f64 = 0.75;

    // Если частота термина равна нулю или нет документов в коллекции,
    // то вклад данного термина в оценку релевантности отсутствует.
    if tf == 0 || n_docs == 0 {
        return 0.0;
    }

    // Вычисление обратной частоты документа (IDF - Inverse Document Frequency).
    // IDF измеряет важность термина: чем реже термин встречается в коллекции,
    // тем выше его вес. Формула использует сглаживание (+0.5) для избежания
    // деления на ноль и логарифма от нуля.
    let idf = ((n_docs as f64 - df as f64 + 0.5) / (df as f64 + 0.5)).ln();

    // Вычисление нормализующего коэффициента, учитывающего длину документа.
    // Длинные документы получают меньший вес, короткие — больший.
    // Формула: 1 - B + B * (длина_документа / средняя_длина)
    let norm = 1.0 - B + B * doc_len as f64 / avg_len;

    // Преобразуем частоту термина из целочисленного типа в вещественный
    // для последующих вычислений с плавающей точкой.
    let tf = tf as f64;

    // Итоговая формула BM25:
    // score = IDF * (tf * (K1 + 1)) / (tf + K1 * norm)
    // Эта часть комбинирует IDF с насыщенной частотой термина,
    // скорректированной на длину документа.
    idf * tf * (K1 + 1.0) / (tf + K1 * norm)
}
```

